using HelpDeskPro.Api.Data; using HelpDeskPro.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Controllers; [ApiController][Route("api/knowledge")][Authorize]
public class KnowledgeController:ControllerBase { private readonly AppDbContext db; public KnowledgeController(AppDbContext db){this.db=db;} int GetUserId()=>int.Parse(User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value); [HttpGet] public async Task<IActionResult> Get()=>Ok(await db.KnowledgeArticles.OrderByDescending(x=>x.UpdatedAt).ToListAsync()); [HttpGet("{id:int}")] public async Task<IActionResult> GetById(int id){var x=await db.KnowledgeArticles.FindAsync(id);return x==null?NotFound():Ok(x);} [Authorize(Roles="Admin,Support")][HttpPost] public async Task<IActionResult> Add(KnowledgeArticle x){x.AuthorId=GetUserId();db.KnowledgeArticles.Add(x);await db.SaveChangesAsync();db.ActivityLogs.Add(new ActivityLog{Action=$"Created article: {x.Title}",Entity="KnowledgeArticle",EntityId=x.Id,UserId=GetUserId()});await db.SaveChangesAsync();return Ok(x);} [Authorize(Roles="Admin,Support")][HttpDelete("{id}")] public async Task<IActionResult> Delete(int id){var x=await db.KnowledgeArticles.FindAsync(id);if(x==null)return NotFound();db.KnowledgeArticles.Remove(x);await db.SaveChangesAsync();db.ActivityLogs.Add(new ActivityLog{Action=$"Deleted article: {x.Title}",Entity="KnowledgeArticle",EntityId=id,UserId=GetUserId()});await db.SaveChangesAsync();return NoContent();} }
